const SOL={"c1":{code:"s = \"devops is fun\"\nprint(\" \".join(s.split()[::-1]))\n",steps:["split() turns the sentence into a list of words: ['devops', 'is', 'fun'].", "[::-1] is a slice with step -1 \u2014 it returns the list reversed.", "\" \".join(...) glues the words back together with single spaces.", "Interview follow-up: reverse in place without slicing \u2014 swap words from both ends with two pointers."],big:"O(n)",pit:["s[::-1] reverses the characters, not the words: 'nuf si spoved'.", "Printing the list shows brackets and quotes instead of a sentence."]},
"c2":{code:"from collections import Counter\ns = \"swiss\"\ncounts = Counter(s)\nfor ch in s:\n    if counts[ch] == 1:\n        print(ch)\n        break\n",steps:["First pass: count every character with Counter (s \u2192 3, w \u2192 1, i \u2192 1).", "Second pass: walk the string in ORIGINAL order and stop at the first character whose count is 1.", "Two passes is O(n) \u2014 much better than calling s.count(ch) for every character, which is O(n\u00b2).", "If no unique character exists, interviews usually expect you to return None or -1 \u2014 say which you'd choose."],big:"O(n)",pit:["Looping over counts instead of s can return the wrong character in older Pythons and hides the 'first' requirement.", "s.count(ch) inside the loop works but is O(n\u00b2)."]},
"c3":{code:"nums = [2, 7, 11, 15]\ntarget = 9\nseen = {}\nfor i, n in enumerate(nums):\n    need = target - n\n    if need in seen:\n        print(seen[need], i)\n        break\n    seen[n] = i\n",steps:["For each number, the partner you need is target - n.", "Keep a dict of value \u2192 index for numbers you've already seen.", "If the partner is already in the dict, you've found the pair: print its index and the current one.", "Otherwise remember the current number and move on.", "One pass, O(n) \u2014 the classic interview answer, versus the O(n\u00b2) double loop."],big:"O(n) time, O(n) space",pit:["The double loop works but is O(n\u00b2) \u2014 interviewers will ask you to improve it.", "Storing the number before checking can pair an element with itself when target = 2 \u00d7 n."]},
"c4":{code:"tests = [\"()[]{}\", \"(]\", \"{[]}\"]\npairs = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\nfor s in tests:\n    stack = []\n    ok = True\n    for ch in s:\n        if ch in \"([{\":\n            stack.append(ch)\n        elif not stack or stack.pop() != pairs[ch]:\n            ok = False\n            break\n    print(ok and not stack)\n",steps:["Use a list as a stack: push every opening bracket.", "On a closing bracket, the top of the stack must be its matching opener \u2014 pop and compare.", "If the stack is empty when a closer arrives, it's invalid.", "At the end the stack must be empty (no unclosed openers).", "This is the classic 'valid parentheses' interview question."],big:"O(n) time, O(n) space",pit:["Only counting brackets misses '(]' \u2014 the order and type matter.", "Forgetting the final empty-stack check accepts '(('."]},
"c5":{code:"items = [3, 1, 3, 2, 1]\nseen = set()\nresult = []\nfor x in items:\n    if x not in seen:\n        seen.add(x)\n        result.append(x)\nprint(result)\n# one-liner: print(list(dict.fromkeys(items)))\n",steps:["A set gives O(1) 'have I seen this?' checks.", "Append an item only the first time you see it, so the original order is kept.", "list(set(items)) removes duplicates but loses order \u2014 that's the trap."],big:"O(n)",pit:["list(set(items)) scrambles the order.", "Checking 'x not in result' (a list) works but is O(n\u00b2)."]},
"c6":{code:"from collections import Counter\ntext = \"the cat and the hat and the bat\"\nword, count = Counter(text.split()).most_common(1)[0]\nprint(word, count)\n",steps:["split() turns the sentence into a list of words.", "Counter counts each word in one pass.", "most_common(1) returns [(word, count)]; take [0] and unpack.", "print(a, b) separates with a single space."],big:"O(n)",pit:["most_common(1) returns a list \u2014 forgetting [0] prints [('the', 3)]."]},
"c7":{code:"from collections import Counter\nlog = \"\"\"INFO start\nERROR disk full\nWARN slow response\nERROR timeout\nINFO done\"\"\"\ncounts = Counter(line.split()[0] for line in log.splitlines())\nfor level in sorted(counts):\n    print(level, counts[level])\n",steps:["splitlines() gives one string per log line.", "line.split()[0] is the first word \u2014 the level.", "Counter tallies them; sorted() orders the keys alphabetically.", "This is the same pattern as a real log-triage script."],big:"O(n log n) for the sort",pit:["Iterating counts without sorted() gives insertion order, not alphabetical."]},
"c8":{code:"data = [[1, 2], [3, [4, 5]], 6]\n\ndef flatten(items):\n    out = []\n    for x in items:\n        if isinstance(x, list):\n            out.extend(flatten(x))\n        else:\n            out.append(x)\n    return out\n\nprint(flatten(data))\n",steps:["Recursion handles any depth: if an item is a list, flatten it first.", "extend() adds each element of the returned list; append() adds a single value.", "The base case is a non-list item \u2014 just append it."],big:"O(total elements)",pit:["Using append for the recursive result nests lists again.", "A single loop only handles one level of nesting."]},
"c9":{code:"import functools\ncalls = {\"n\": 0}\n\ndef retry(times):\n    def decorator(fn):\n        @functools.wraps(fn)\n        def wrapper(*args, **kwargs):\n            for attempt in range(times):\n                try:\n                    return fn(*args, **kwargs)\n                except Exception:\n                    if attempt == times - 1:\n                        raise\n        return wrapper\n    return decorator\n\n@retry(3)\ndef flaky():\n    calls[\"n\"] += 1\n    if calls[\"n\"] < 3:\n        raise ConnectionError(\"try again\")\n    return \"ok\"\n\nprint(flaky())\n",steps:["A decorator WITH arguments needs three layers: retry(times) \u2192 decorator(fn) \u2192 wrapper(*args, **kwargs).", "wrapper loops up to times, calling fn inside try.", "Return on the first success; on the last failed attempt, re-raise so errors aren't swallowed.", "functools.wraps keeps the original function's name \u2014 interviewers notice.", "In production you'd add a sleep with exponential backoff and jitter between attempts."],big:"O(times)",pit:["Two layers only (no outer retry(times)) breaks @retry(3).", "Swallowing the final exception hides real failures."]},
"c10":{code:"nums = [0, 1, 0, 3, 12]\nnon_zero = [n for n in nums if n != 0]\nresult = non_zero + [0] * (len(nums) - len(non_zero))\nprint(result)\n",steps:["Keep the non-zero numbers in their original order with a comprehension.", "Append as many zeroes as you removed: len(nums) - len(non_zero).", "Follow-up interviewers ask: do it in place with two pointers \u2014 a write index that advances on each non-zero, then fill the rest with zeroes."],big:"O(n)",pit:["sorting the list changes the order of non-zero numbers."]},
"f_top_ips":{code:"from collections import Counter\n\ndef top_ips(log, n):\n    counts = Counter(line.split()[0] for line in log.splitlines() if line.strip())\n    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))\n    return [ip for ip, _ in ranked[:n]]\n",steps:["Take the first field of each non-empty line \u2014 that's the client IP.", "Count with Counter.", "Sort by (-count, ip): negative count gives most frequent first; ip breaks ties alphabetically.", "Slice the top n and keep only the IPs.", "Same idea as: awk '{print $1}' access.log | sort | uniq -c | sort -rn | head"],big:"O(n + k log k)",pit:["Counter.most_common doesn't break ties by IP.", "An empty string has no lines \u2014 skip blanks or you'll hit IndexError."]},
"f_disk_alerts":{code:"def disk_alerts(usage, threshold):\n    return sorted(mount for mount, pct in usage.items() if pct >= threshold)\n",steps:["Loop over (mount, percent) pairs with .items().", "Keep mounts at or ABOVE the threshold (>=, not >).", "sorted() returns a new sorted list."],big:"O(k log k)",pit:["Using > misses a mount exactly at the threshold."]},
"f_is_valid_ipv4":{code:"def is_valid_ipv4(s):\n    parts = s.split(\".\")\n    if len(parts) != 4:\n        return False\n    for p in parts:\n        if not p.isdigit():\n            return False\n        if str(int(p)) != p:      # rejects leading zeros like '01'\n            return False\n        if int(p) > 255:\n            return False\n    return True\n",steps:["Split on dots \u2014 there must be exactly 4 parts.", "Each part must be all digits (rejects '', '-1', 'a').", "str(int(p)) == p rejects leading zeros such as '01'.", "Each value must be \u2264 255.", "In real code, the standard library does this: ipaddress.ip_address(s)."],big:"O(1)",pit:["int('01') == 1 quietly accepts leading zeros.", "Forgetting the length check accepts '1.2.3'."]},
"f_merge_intervals":{code:"def merge_intervals(intervals):\n    merged = []\n    for start, end in sorted(intervals):\n        if merged and start <= merged[-1][1]:\n            merged[-1][1] = max(merged[-1][1], end)\n        else:\n            merged.append([start, end])\n    return merged\n",steps:["Sort by start so overlapping intervals sit next to each other.", "Compare each interval with the last merged one.", "If it starts before (or exactly when) the last one ends, extend the end with max().", "Otherwise it's a new, separate interval.", "Real-world use: merging maintenance windows or outage periods."],big:"O(n log n)",pit:["Skipping the sort misses overlaps that are out of order.", "Using < instead of <= fails to merge touching intervals like [1,4],[4,5].", "Forgetting max() shrinks an interval that fully contains the next."]},
"f_parse_kv":{code:"def parse_kv(line):\n    return dict(part.split(\"=\", 1) for part in line.split())\n",steps:["split() with no argument splits on any whitespace and ignores extra spaces.", "split('=', 1) splits only on the FIRST '=', so values containing '=' survive.", "dict() accepts an iterable of 2-item pairs."],big:"O(n)",pit:["split('=') without maxsplit breaks values like 'a=b'."]},
"f_latest_version":{code:"def latest_version(versions):\n    return max(versions, key=lambda v: tuple(int(x) for x in v.split(\".\")))\n",steps:["String comparison is wrong: '1.9.3' > '1.10.0' alphabetically.", "Convert each version to a tuple of ints: (1, 10, 0).", "Tuples compare element by element, which is exactly semantic-version order.", "max(..., key=...) returns the original string with the biggest key."],big:"O(n)",pit:["max(versions) compares strings and picks '1.9.3'."]},
"f_count_status":{code:"def count_status(lines):\n    counts = {}\n    for line in lines:\n        status = line.split()[8]\n        counts[status] = counts.get(status, 0) + 1\n    return counts\n",steps:["In the common nginx log format, splitting on spaces puts the status code at index 8.", "dict.get(key, 0) + 1 counts without a KeyError.", "Keep the codes as strings \u2014 the tests expect '200', not 200."],big:"O(n)",pit:["Index 9 is the response size, not the status.", "Converting to int changes the dict keys."]},
"f_is_anagram":{code:"def is_anagram(a, b):\n    norm = lambda s: sorted(s.replace(\" \", \"\").lower())\n    return norm(a) == norm(b)\n",steps:["Normalise both strings: remove spaces and lower-case them.", "Two strings are anagrams when their sorted letters match.", "Alternative O(n): compare collections.Counter of each."],big:"O(n log n)",pit:["Comparing set(a) == set(b) ignores letter counts \u2014 'aab' vs 'abb' would wrongly match."]}};
Object.assign(SOL,{"f_valid_brackets": {"code": "def is_balanced(s):\n    pairs = {')': '(', ']': '[', '}': '{'}\n    stack = []\n    for ch in s:\n        if ch in '([{':\n            stack.append(ch)\n        elif ch in pairs:\n            if not stack or stack.pop() != pairs[ch]:\n                return False\n    return not stack\n", "steps": ["A stack remembers the openers still waiting to be closed, most recent on top.", "A closer must match the most recent opener — that's the order rule.", "A closer with an empty stack means nothing to close: return False straight away.", "Leftover openers at the end mean something was never closed."], "big": "O(n) time, O(n) space", "pit": ["Counting brackets misses order: ([)] has equal counts but is invalid.", "Forgetting the empty-stack check makes ']' crash with IndexError on pop()."]}, "f_group_anagrams": {"code": "from collections import defaultdict\n\ndef group_anagrams(words):\n    groups = defaultdict(list)\n    for w in words:\n        groups[''.join(sorted(w))].append(w)\n    return sorted(sorted(g) for g in groups.values())\n", "steps": ["Anagrams share a signature: their letters in sorted order. 'eat', 'tea' and 'ate' all become 'aet'.", "defaultdict(list) lets you append without checking whether the key exists.", "Sort inside each group, then sort the groups, so the answer is deterministic.", "Follow-up: a 26-letter count tuple as the key avoids sorting each word — O(k) instead of O(k log k)."], "big": "O(n · k log k) for n words of length k", "pit": ["Comparing every pair of words is O(n²) — too slow for big inputs.", "Returning dict.values() directly gives a view, not a list, in arbitrary order."]}, "f_config_diff": {"code": "def config_diff(old, new):\n    o, n = set(old), set(new)\n    return {\n        \"added\": sorted(n - o),\n        \"removed\": sorted(o - n),\n        \"changed\": sorted(k for k in o & n if old[k] != new[k]),\n    }\n", "steps": ["set(d) gives the keys of a dict.", "n - o: keys only in the new config; o - n: keys only in the old one.", "o & n: keys in both — only those can have changed values.", "This is the core of drift detection, like terraform plan or kubectl diff."], "big": "O(n log n) for sorting the keys", "pit": ["Comparing old[k] for a key that only exists in new raises KeyError.", "Returning sets fails the test — the spec asks for sorted lists."]}, "f_top_k": {"code": "from collections import Counter\n\ndef top_k(nums, k):\n    c = Counter(nums)\n    return [n for n, _ in sorted(c.items(), key=lambda x: (-x[1], x[0]))[:k]]\n", "steps": ["Counter builds number → count in one pass.", "Sorting by (-count, number) puts the most frequent first and breaks ties by the smaller number.", "Slicing [:k] is safe even when k is bigger than the number of distinct values.", "Follow-up: heapq.nsmallest(k, ...) is O(n log k) when k is small."], "big": "O(n log n); O(n log k) with a heap", "pit": ["Counter.most_common() breaks ties by first appearance, not by value — so the tie rule fails.", "Sorting by count alone gives an unstable order on ties."]}, "f_longest_unique": {"code": "def longest_unique(s):\n    last = {}\n    start = best = 0\n    for i, ch in enumerate(s):\n        if ch in last and last[ch] >= start:\n            start = last[ch] + 1\n        last[ch] = i\n        best = max(best, i - start + 1)\n    return best\n", "steps": ["The window s[start:i+1] always holds unique characters.", "On a repeat that's inside the window, jump start past the earlier copy — no need to shrink one step at a time.", "The check last[ch] >= start ignores old copies that are already outside the window ('abba').", "Each character is visited once, so it's linear."], "big": "O(n) time, O(alphabet) space", "pit": ["Without the last[ch] >= start check, 'abba' moves start backwards and returns 3.", "Checking every substring is O(n³)."]}, "f_bsearch": {"code": "def search(nums, target):\n    lo, hi = 0, len(nums) - 1\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[mid] < target:\n            lo = mid + 1\n        else:\n            hi = mid - 1\n    return -1\n", "steps": ["Each step halves the search range, so a million items take about 20 steps.", "lo <= hi (not <) so a one-element range is still checked.", "mid + 1 and mid - 1 guarantee progress — otherwise it can loop forever.", "DevOps use: git bisect is binary search over commits."], "big": "O(log n)", "pit": ["lo = mid instead of mid + 1 can loop forever on two elements.", "while lo < hi skips checking the last remaining element."]}, "f_flatten": {"code": "def flatten(items):\n    out = []\n    for x in items:\n        if isinstance(x, list):\n            out.extend(flatten(x))\n        else:\n            out.append(x)\n    return out\n", "steps": ["Recursion matches the shape of the data: a list can contain lists.", "isinstance(x, list) decides between going deeper and keeping the value.", "extend adds the items of the flattened sublist; append would nest it again.", "Follow-up: very deep nesting hits the recursion limit — use an explicit stack."], "big": "O(total items)", "pit": ["Treating strings as iterables explodes 'abc' into letters — check for list specifically.", "append(flatten(x)) re-nests the result."]}, "f_human_bytes": {"code": "def human(n):\n    if n < 1024:\n        return f\"{n} B\"\n    size = float(n)\n    for unit in [\"KiB\", \"MiB\", \"GiB\", \"TiB\"]:\n        size /= 1024\n        if size < 1024 or unit == \"TiB\":\n            return f\"{size:.1f} {unit}\"\n", "steps": ["Bytes are a special case: no decimal.", "Each step up divides by 1024 (binary units: KiB, MiB…).", "Stop at the first unit where the value drops under 1024, or at the largest unit.", "f\"{size:.1f}\" rounds to one decimal place."], "big": "O(1)", "pit": ["Using 1000 gives SI units (kB, MB) — a different standard.", "Forgetting the last-unit guard returns None for huge numbers."]}, "f_semver": {"code": "def compare(a, b):\n    x = [int(p) for p in a.split('.')]\n    y = [int(p) for p in b.split('.')]\n    n = max(len(x), len(y))\n    x += [0] * (n - len(x))\n    y += [0] * (n - len(y))\n    return (x > y) - (x < y)\n", "steps": ["Versions compare as numbers per part, not as strings: 10 > 9 even though '10' < '9' as text.", "Padding with zeros makes '1.2' and '1.2.0' the same length and equal.", "Python compares lists element by element, which is exactly version order.", "(x > y) - (x < y) turns two booleans into -1, 0 or 1."], "big": "O(parts)", "pit": ["Comparing the strings directly says '1.10.0' < '1.9.3'.", "Not padding makes [1,2] < [1,2,0], so equal versions look different."]}, "f_dedupe": {"code": "def dedupe(items):\n    seen = set()\n    out = []\n    for x in items:\n        if x not in seen:\n            seen.add(x)\n            out.append(x)\n    return out\n", "steps": ["A set gives O(1) membership checks.", "The output list keeps the order of first appearance.", "One-liner alternative: list(dict.fromkeys(items)) — dicts keep insertion order.", "list(set(items)) loses the order — the classic trap."], "big": "O(n)", "pit": ["list(set(items)) scrambles the order.", "Checking 'x not in out' on the list makes it O(n²)."]}, "f_busiest_window": {"code": "def busiest(ts, w):\n    ts = sorted(ts)\n    best = left = 0\n    for right, t in enumerate(ts):\n        while t - ts[left] >= w:\n            left += 1\n        best = max(best, right - left + 1)\n    return best\n", "steps": ["Sorting turns the problem into a sliding window over a line.", "The window [ts[left], t] is valid while t - ts[left] < w.", "Each pointer only moves forward, so the scan is linear after sorting.", "Real-world use: rate limiting and finding traffic spikes in logs."], "big": "O(n log n)", "pit": ["Using <= w instead of < w counts a request exactly w seconds later in the same window.", "Bucketing by calendar minute misses windows that cross a minute boundary."]}, "f_rotate_logs": {"code": "import re\n\ndef to_delete(files, keep):\n    logs = []\n    for f in files:\n        m = re.fullmatch(r\"app\\.log\\.(\\d+)\", f)\n        if m:\n            logs.append((int(m.group(1)), f))\n    logs.sort()\n    return [f for _, f in reversed(logs[keep:])]\n", "steps": ["re.fullmatch makes sure the whole name matches, so notes.txt is skipped.", "Sort by the number, not the text — otherwise app.log.10 sorts before app.log.2.", "logs[keep:] is everything older than the newest keep files.", "Reversing lists the oldest first, the order you'd delete in."], "big": "O(n log n)", "pit": ["Sorting names as text puts app.log.10 between 1 and 2.", "re.match accepts 'app.log.3.bak' because it only anchors at the start."]}});
