CHAL.push({id:'f_top_error_codes',name:`Top error codes (2 GB log)`,diff:'medium',fn:'top_error_codes',info:`Return the n most frequent codes from tokens like <code>code=E503</code>, most frequent first, ties by code. Assume the input could be a 2 GB file: iterate line by line, never load it all.`,hint:`Loop over lines, split each, keep tokens starting with code=, count with Counter, sort by (-count, code). Iterating a file object reads one line at a time.`,start:"def top_error_codes(lines, n):\n    # lines can be ANY iterable \u2014 e.g. an open 2 GB file \u2014 so never load it all\n    pass\n",tests:[[[["2026-11-21T10:00 ERROR code=E503 svc=api", "2026-11-21T10:01 INFO ok", "2026-11-21T10:02 ERROR code=E500 svc=db", "2026-11-21T10:03 ERROR code=E503 svc=api", "2026-11-21T10:04 WARN code=W101", "2026-11-21T10:05 ERROR code=E500 svc=api", "2026-11-21T10:06 ERROR code=E503 svc=web"], 2], ["E503", "E500"]], [[["2026-11-21T10:00 ERROR code=E503 svc=api", "2026-11-21T10:01 INFO ok", "2026-11-21T10:02 ERROR code=E500 svc=db", "2026-11-21T10:03 ERROR code=E503 svc=api", "2026-11-21T10:04 WARN code=W101", "2026-11-21T10:05 ERROR code=E500 svc=api", "2026-11-21T10:06 ERROR code=E503 svc=web"], 10], ["E503", "E500", "W101"]], [[["INFO ok"], 3], []]]},
{id:'f_flaky_tests',name:`Flaky tests (SQL)`,diff:'medium',fn:'flaky_tests',info:`Using SQL on the test_runs table, return tests that failed at least 3 of their LAST 10 runs, sorted by name. The setup is done for you — write the query.`,hint:`Rank runs per test with ROW_NUMBER() OVER (PARTITION BY test_name ORDER BY started_at DESC), keep rn <= 10 and status = 'fail', then GROUP BY test_name HAVING COUNT(*) >= 3.`,start:"import sqlite3\n\ndef flaky_tests(rows):\n    # rows: [run_id, test_name, status, started_at]\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE test_runs(run_id INTEGER, test_name TEXT, status TEXT, started_at TEXT)\")\n    con.executemany(\"INSERT INTO test_runs VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    -- write SQL: tests that failed at least 3 of their last 10 runs, sorted by name\n    \"\"\"\n    return [r[0] for r in con.execute(query)]\n",tests:[[[[[1, "test_login", "fail", "2026-11-01"], [2, "test_login", "fail", "2026-11-02"], [3, "test_login", "pass", "2026-11-03"], [4, "test_login", "fail", "2026-11-04"], [5, "test_login", "pass", "2026-11-05"], [6, "test_login", "pass", "2026-11-06"], [7, "test_login", "fail", "2026-11-07"], [8, "test_login", "pass", "2026-11-08"], [9, "test_login", "pass", "2026-11-09"], [10, "test_login", "fail", "2026-11-10"], [11, "test_login", "pass", "2026-11-11"], [12, "test_login", "pass", "2026-11-12"], [100, "test_upload", "fail", "2026-11-01"], [101, "test_upload", "fail", "2026-11-02"], [102, "test_upload", "fail", "2026-11-03"], [103, "test_upload", "pass", "2026-11-04"], [104, "test_upload", "pass", "2026-11-05"], [105, "test_upload", "pass", "2026-11-06"], [106, "test_upload", "pass", "2026-11-07"], [107, "test_upload", "pass", "2026-11-08"], [108, "test_upload", "pass", "2026-11-09"], [109, "test_upload", "pass", "2026-11-10"], [110, "test_upload", "pass", "2026-11-11"], [111, "test_upload", "pass", "2026-11-12"], [200, "test_api", "fail", "2026-11-01"], [201, "test_api", "fail", "2026-11-02"], [202, "test_api", "fail", "2026-11-03"], [300, "test_ui", "pass", "2026-11-01"], [301, "test_ui", "pass", "2026-11-02"], [302, "test_ui", "pass", "2026-11-03"], [303, "test_ui", "pass", "2026-11-04"], [304, "test_ui", "pass", "2026-11-05"]]], ["test_api", "test_login"]], [[[[100, "test_upload", "fail", "2026-11-01"], [101, "test_upload", "fail", "2026-11-02"], [102, "test_upload", "fail", "2026-11-03"], [103, "test_upload", "pass", "2026-11-04"], [104, "test_upload", "pass", "2026-11-05"], [105, "test_upload", "pass", "2026-11-06"], [106, "test_upload", "pass", "2026-11-07"], [107, "test_upload", "pass", "2026-11-08"], [108, "test_upload", "pass", "2026-11-09"], [109, "test_upload", "pass", "2026-11-10"], [110, "test_upload", "pass", "2026-11-11"], [111, "test_upload", "pass", "2026-11-12"], [300, "test_ui", "pass", "2026-11-01"], [301, "test_ui", "pass", "2026-11-02"], [302, "test_ui", "pass", "2026-11-03"], [303, "test_ui", "pass", "2026-11-04"], [304, "test_ui", "pass", "2026-11-05"]]], []], [[[]], []]]});
SOL.f_top_error_codes={code:"from collections import Counter\n\ndef top_error_codes(lines, n):\n    counts = Counter()\n    for line in lines:                 # one line at a time: constant memory\n        for token in line.split():\n            if token.startswith(\"code=\"):\n                counts[token[5:]] += 1\n    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))\n    return [code for code, _ in ranked[:n]]\n\n# real use on a huge file:\n# with open(\"app.log\") as f:\n#     print(top_error_codes(f, 10))\n",steps:["Iterate lines lazily \u2014 a file object yields one line at a time, so memory stays constant even for 2 GB.", "Split each line and keep only tokens that start with code=.", "Count with Counter (a dict subclass) in one pass.", "Sort by (-count, code) and slice the first n.", "Mention in interviews: for multi-GB logs you could also use awk/grep, or split the file and count in parallel processes, then merge the Counters."],big:"O(L) time over all lines, O(k) memory for k distinct codes",pit:["f.read() or readlines() loads the whole 2 GB into memory.", "Counter.most_common doesn't break ties by code."]};
SOL.f_flaky_tests={code:"import sqlite3\n\ndef flaky_tests(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE test_runs(run_id INTEGER, test_name TEXT, status TEXT, started_at TEXT)\")\n    con.executemany(\"INSERT INTO test_runs VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    WITH ranked AS (\n      SELECT test_name, status,\n             ROW_NUMBER() OVER (PARTITION BY test_name ORDER BY started_at DESC) AS rn\n      FROM test_runs\n    )\n    SELECT test_name\n    FROM ranked\n    WHERE rn <= 10 AND status = 'fail'\n    GROUP BY test_name\n    HAVING COUNT(*) >= 3\n    ORDER BY test_name\n    \"\"\"\n    return [r[0] for r in con.execute(query)]\n",steps:["'Last 10 runs per test' is a top-N-per-group problem \u2014 the classic use for a window function.", "ROW_NUMBER() OVER (PARTITION BY test_name ORDER BY started_at DESC) numbers each test's runs from newest (1) to oldest.", "Keep rn <= 10 to look only at the last 10, and only failed rows.", "GROUP BY test_name HAVING COUNT(*) >= 3 keeps tests with 3+ of those failures.", "This exact question is in your career report's readiness check."],big:"O(N log N) for the sort inside the window",pit:["Filtering status = 'fail' BEFORE ranking counts the last 10 failures, not the last 10 runs.", "WHERE COUNT(*) >= 3 is invalid \u2014 aggregates need HAVING.", "Forgetting DESC ranks the oldest runs as the 'last 10'."]};
