/* write-it-yourself tasks for the new lessons */
[['o16',T('cmd',`You edited app.service. Reload systemd, then make the service start now and at every boot.`,`systemctl daemon-reload && systemctl enable --now app`,{checks:[['daemon-reload','reload unit files after editing'],['enable','enable it at boot'],['(--now|start|restart)','start it now']]})],
 ['o17',T('explain',`Explain how you'd prepare and install a CA-signed certificate for a server, and how you'd check it.`,`Generate a private key and a CSR with every hostname in the SAN; have the CA sign it; install the leaf with its intermediate chain; make sure clients trust the CA; verify with openssl s_client (chain, hostname, dates); add expiry monitoring and automate renewal.`,{rubric:['Private key and CSR with the right SANs','CA signs it; install the leaf plus intermediate chain','Clients trust the CA (trust store / keystore)','Verify with openssl s_client: chain, hostname, dates','Expiry monitoring and automated renewal']})],
 ['o19',T('explain',`A release pipeline takes 40 minutes and fails randomly. How would you make it fast and trustworthy?`,`Measure each stage first. Cache dependencies; run independent stages and tests in parallel (matrix, sharding); build once and promote the same artefact; quarantine flaky tests with tickets and fix root causes; use clean ephemeral runners; publish test reports always; track duration and failure rate over time.`,{rubric:['Measure stage timings first','Cache dependencies and parallelise','Build once, promote the same artefact','Quarantine and fix flaky tests (not blind retries)','Clean ephemeral runners and reports on every run']})],
 ['k14',T('explain',`Design a backup service for 500 servers. Walk through the key parts.`,`Start with RPO, RTO, retention and data size/change rate. Agents on servers, a scheduler, a backup server with a catalog database, deduplicated storage pools, an off-site or immutable copy, protection of the catalog itself, monitoring, and regular restore tests that measure RTO.`,{rubric:['Requirements first: RPO, RTO, retention, size and change rate','Agents, scheduler and a catalog database','Deduplicated storage tiers (disk/object/tape)','Off-site or immutable copy; catalog protected too','Monitoring and regular measured restore tests']})],
 ['a9',T('explain',`How would you plan system testing for a new release of an enterprise product?`,`Agree entry and exit criteria; map customer-like scenarios across platforms and integrations; design realistic workloads (data, churn, concurrency); plan resiliency tests with failure injection and recovery checks; run soak tests; collect metrics and logs on one timeline; triage by owner; report readiness honestly.`,{rubric:['Entry and exit criteria','Customer-like scenarios across platforms and integrations','Realistic workloads plus soak tests','Failure injection and recovery checks','Evidence-based triage and honest readiness reporting']})]
].forEach(([id,t])=>{const l=ALL.find(x=>x.id===id);if(l){t.k=l.id+':'+l.steps.length;l.steps.push(t)}});

FEED.push({d:`2026-11-21`,items:[`8 new lessons: processes & systemd, TLS & certificates, Ansible, Jenkins & GitHub Actions, design a backup service, design a rate limiter, system testing at scale, asyncio & dataclasses.`,`22 more reported interview questions (HSBC, Qualcomm, Microsoft, Amgen, F5, SDET loops), each linked to its source.`,`New HR & offer deck: notice period, CTC, counter-offers, comparing and negotiating offers.`,`More personal answers in Your story and Behavioural, built from your real work.`]});

/* round 2: tasks and role links for the newest lessons */
[['o20',T('cmd',`Find which process is listening on TCP port 8080, showing numeric ports and the owning process.`,`ss -tlnp | grep :8080`,{checks:[['\\bss\\b|netstat|lsof','use ss (or netstat/lsof)'],['-[a-z]*t','TCP sockets (-t)'],['-[a-z]*l|LISTEN','listening sockets (-l)'],['-[a-z]*p|lsof','show the process (-p)'],['8080','filter for port 8080']]})],
 ['o21',T('explain',`A Kubernetes Service gets no traffic to its pods. Walk through how you'd debug it.`,`Check endpoints (empty means selector/label mismatch or pods not Ready); compare the selector with pod labels; check readiness probes; check port vs targetPort vs containerPort; test from inside the cluster with a temporary pod (DNS name and curl); check NetworkPolicies; then the Ingress rules and controller logs.`,{rubric:['Endpoints: selector vs labels, pods Ready','Readiness probes','port / targetPort / containerPort','Test from inside the cluster (DNS + curl)','NetworkPolicy and Ingress rules/controller logs']})],
 ['k17',T('explain',`Error rates jump right after a release. Walk through how you run the incident.`,`Declare an incident and severity; assign commander, ops and comms; mitigate first by rolling back or switching off the feature; confirm recovery with metrics; communicate on a schedule; keep a timeline; afterwards a blameless postmortem with owned, dated actions.`,{rubric:['Declare and set severity','Assign roles (commander, ops, comms)','Mitigate first: rollback/feature flag','Confirm recovery with metrics; regular updates','Blameless postmortem with owned actions']})]
].forEach(([id,t])=>{const l=ALL.find(x=>x.id===id);if(l){t.k=l.id+':'+l.steps.length;l.steps.push(t)}});
