/* SQL drills (sqlite runs in the browser) */
CHAL.push(
{"id": "sql_dupes", "name": "Duplicate emails (SQL)", "diff": "easy", "fn": "dupes", "info": "Table <code>users(id, email)</code>. Return <code>[email, count]</code> for every email that appears more than once, sorted by email.", "hint": "GROUP BY email, keep groups with HAVING COUNT(*) > 1, ORDER BY email.", "start": "import sqlite3\n\ndef dupes(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE users(id INTEGER, email TEXT)\")\n    con.executemany(\"INSERT INTO users VALUES (?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "tests": [[[[[1, "a@x.com"], [2, "b@x.com"], [3, "a@x.com"], [4, "c@x.com"], [5, "c@x.com"], [6, "c@x.com"]]], [["a@x.com", 2], ["c@x.com", 3]]], [[[[1, "a@x.com"]]], []]]},
{"id": "sql_second", "name": "Second-highest salary (SQL)", "diff": "easy", "fn": "second_highest", "info": "Table <code>emp(id, name, salary)</code>. Return the second-highest <b>distinct</b> salary, or <code>None</code> if there isn't one.", "hint": "Order the DISTINCT salaries descending and skip the first: LIMIT 1 OFFSET 1.", "start": "import sqlite3\n\ndef second_highest(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE emp(id INTEGER, name TEXT, salary INTEGER)\")\n    con.executemany(\"INSERT INTO emp VALUES (?,?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    row = con.execute(query).fetchone()\n    return row[0] if row else None\n", "tests": [[[[[1, "a", 100], [2, "b", 300], [3, "c", 200], [4, "d", 300]]], 200], [[[[1, "a", 100], [2, "b", 100]]], null], [[[]], null]]},
{"id": "sql_nodept", "name": "Departments with no staff (SQL)", "diff": "easy", "fn": "empty_depts", "info": "Tables are combined for you as one list of rows: <code>[kind, id, name, dept_id]</code> where kind is \"dept\" or \"emp\". Return the names of departments with no employees, sorted.", "hint": "LEFT JOIN dept to emp on the department id and keep rows where the employee side IS NULL.", "start": "import sqlite3\n\ndef empty_depts(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE t(kind TEXT, id INTEGER, name TEXT, dept_id INTEGER)\")\n    con.executemany(\"INSERT INTO t VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    return [r[0] for r in con.execute(query)]\n", "tests": [[[[["dept", 1, "Ops", null], ["dept", 2, "QA", null], ["dept", 3, "Sec", null], ["emp", 10, "Asha", 1], ["emp", 11, "Ravi", 1], ["emp", 12, "Meena", 3]]], ["QA"]], [[[["dept", 1, "Ops", null]]], ["Ops"]]]},
{"id": "sql_topdept", "name": "Top earner per department (SQL)", "diff": "medium", "fn": "top_per_dept", "info": "Table <code>emp(id, name, dept, salary)</code>. Return <code>[dept, name]</code> for the highest-paid person in each department (ties: lower id wins), sorted by dept.", "hint": "ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC, id) and keep rn = 1.", "start": "import sqlite3\n\ndef top_per_dept(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE emp(id INTEGER, name TEXT, dept TEXT, salary INTEGER)\")\n    con.executemany(\"INSERT INTO emp VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "tests": [[[[[1, "Asha", "ops", 90], [2, "Ravi", "ops", 120], [3, "Meena", "qa", 80], [4, "Kiran", "qa", 80], [5, "Dev", "sec", 70]]], [["ops", "Ravi"], ["qa", "Meena"], ["sec", "Dev"]]]]},
{"id": "sql_errrate", "name": "Error rate per service (SQL)", "diff": "medium", "fn": "error_rates", "info": "Table <code>req(service, status)</code>. Return <code>[service, total, errors, pct]</code> where errors are status ≥ 500 and pct is rounded to 1 decimal; sort by pct descending, then service.", "hint": "COUNT(*) for total, SUM(CASE WHEN status >= 500 THEN 1 ELSE 0 END) for errors, and multiply by 100.0 before dividing.", "start": "import sqlite3\n\ndef error_rates(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE req(service TEXT, status INTEGER)\")\n    con.executemany(\"INSERT INTO req VALUES (?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "tests": [[[[["api", 200], ["api", 500], ["api", 503], ["api", 200], ["web", 200], ["web", 404], ["db", 500]]], [["db", 1, 1, 100.0], ["api", 4, 2, 50.0], ["web", 2, 0, 0.0]]]]},
{"id": "sql_running", "name": "Backup volume running total (SQL)", "diff": "medium", "fn": "running_total", "info": "Table <code>backups(day, gb)</code> with several rows per day. Return <code>[day, gb_that_day, running_total]</code> ordered by day.", "hint": "Aggregate per day first, then SUM(...) OVER (ORDER BY day) on the daily totals.", "start": "import sqlite3\n\ndef running_total(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE backups(day TEXT, gb INTEGER)\")\n    con.executemany(\"INSERT INTO backups VALUES (?,?)\", rows)\n    query = \"\"\"\n    -- write your SQL here\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "tests": [[[[["2026-11-01", 10], ["2026-11-01", 5], ["2026-11-02", 20], ["2026-11-03", 1], ["2026-11-03", 4]]], [["2026-11-01", 15, 15], ["2026-11-02", 20, 35], ["2026-11-03", 5, 40]]]]}
);
Object.assign(SOL,{"sql_dupes": {"code": "import sqlite3\n\ndef dupes(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE users(id INTEGER, email TEXT)\")\n    con.executemany(\"INSERT INTO users VALUES (?,?)\", rows)\n    query = \"\"\"\n    SELECT email, COUNT(*) FROM users\n    GROUP BY email HAVING COUNT(*) > 1\n    ORDER BY email\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "steps": ["GROUP BY collapses rows with the same email into one group.", "HAVING filters groups after counting — WHERE can't see COUNT(*).", "ORDER BY makes the output deterministic."], "big": "O(n log n) for the sort/grouping", "pit": ["Using WHERE COUNT(*) > 1 is an error: aggregates belong in HAVING.", "Forgetting ORDER BY gives rows in arbitrary order."]}, "sql_second": {"code": "import sqlite3\n\ndef second_highest(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE emp(id INTEGER, name TEXT, salary INTEGER)\")\n    con.executemany(\"INSERT INTO emp VALUES (?,?,?)\", rows)\n    query = \"\"\"\n    SELECT DISTINCT salary FROM emp\n    ORDER BY salary DESC\n    LIMIT 1 OFFSET 1\n    \"\"\"\n    row = con.execute(query).fetchone()\n    return row[0] if row else None\n", "steps": ["DISTINCT removes the tie at 300 so it isn't counted twice.", "ORDER BY salary DESC puts the highest first; OFFSET 1 skips it.", "fetchone() returns None when there's no second value — handle that."], "big": "O(n log n) for the sort/grouping", "pit": ["Without DISTINCT, two people on 300 make 300 the 'second highest'.", "MAX(salary) WHERE salary < MAX(...) also works; know both."]}, "sql_nodept": {"code": "import sqlite3\n\ndef empty_depts(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE t(kind TEXT, id INTEGER, name TEXT, dept_id INTEGER)\")\n    con.executemany(\"INSERT INTO t VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    SELECT d.name FROM t d\n    LEFT JOIN t e ON e.kind = 'emp' AND e.dept_id = d.id\n    WHERE d.kind = 'dept' AND e.id IS NULL\n    ORDER BY d.name\n    \"\"\"\n    return [r[0] for r in con.execute(query)]\n", "steps": ["LEFT JOIN keeps every department, matched or not.", "Unmatched departments have NULL on the employee side.", "WHERE e.id IS NULL keeps only those — the anti-join pattern."], "big": "O(n log n) for the sort/grouping", "pit": ["An INNER JOIN drops exactly the departments you're looking for.", "Putting e.kind = 'emp' in WHERE instead of ON turns the LEFT JOIN back into an inner join."]}, "sql_topdept": {"code": "import sqlite3\n\ndef top_per_dept(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE emp(id INTEGER, name TEXT, dept TEXT, salary INTEGER)\")\n    con.executemany(\"INSERT INTO emp VALUES (?,?,?,?)\", rows)\n    query = \"\"\"\n    SELECT dept, name FROM (\n      SELECT dept, name,\n             ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC, id) AS rn\n      FROM emp\n    ) WHERE rn = 1\n    ORDER BY dept\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "steps": ["PARTITION BY dept restarts the numbering in each department.", "ORDER BY salary DESC, id puts the top earner first and breaks ties by id.", "Filtering rn = 1 must happen outside the window query."], "big": "O(n log n) for the sort/grouping", "pit": ["GROUP BY dept with MAX(salary) can't tell you the name reliably.", "Filtering rn in the same SELECT fails — window results aren't available in WHERE."]}, "sql_errrate": {"code": "import sqlite3\n\ndef error_rates(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE req(service TEXT, status INTEGER)\")\n    con.executemany(\"INSERT INTO req VALUES (?,?)\", rows)\n    query = \"\"\"\n    SELECT service, COUNT(*) AS total,\n           SUM(CASE WHEN status >= 500 THEN 1 ELSE 0 END) AS errors,\n           ROUND(100.0 * SUM(CASE WHEN status >= 500 THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct\n    FROM req GROUP BY service\n    ORDER BY pct DESC, service\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "steps": ["CASE inside SUM counts only matching rows — conditional aggregation.", "100.0 forces decimal division; 100 would do integer division.", "ROUND(x, 1) gives one decimal place."], "big": "O(n log n) for the sort/grouping", "pit": ["Integer division turns 2/4 into 0.", "Counting 4xx as errors changes the answer — read the definition carefully."]}, "sql_running": {"code": "import sqlite3\n\ndef running_total(rows):\n    con = sqlite3.connect(\":memory:\")\n    con.execute(\"CREATE TABLE backups(day TEXT, gb INTEGER)\")\n    con.executemany(\"INSERT INTO backups VALUES (?,?)\", rows)\n    query = \"\"\"\n    SELECT day, daily, SUM(daily) OVER (ORDER BY day) AS running\n    FROM (SELECT day, SUM(gb) AS daily FROM backups GROUP BY day)\n    ORDER BY day\n    \"\"\"\n    return [list(r) for r in con.execute(query)]\n", "steps": ["The inner query collapses each day to one total.", "SUM() OVER (ORDER BY day) adds up everything up to the current row.", "Ordering by an ISO date string sorts chronologically."], "big": "O(n log n) for the sort/grouping", "pit": ["A window over raw rows double-counts days with several rows.", "Without ORDER BY in OVER(), you get the grand total on every row."]}});
FEED.push({d:`2026-11-21`,items:[`Prep tab: Syllabus (what you must know for each target role, by week), Guides (16 offline cheat sheets and playbooks) and Official docs (75+ primary sources, searchable).`,`6 more lessons: performance & network tools, Kubernetes networking, Helm, Azure fundamentals, databases for operations, incident management.`,`6 SQL drills that run real SQL in the browser.`]});
